//! Embedded panel files, their cache policy and precompressed variants.
use std::{borrow::Cow, sync::OnceLock};

use axum::{
    body::Body,
    extract::Path,
    http::{HeaderMap, HeaderValue, StatusCode, header},
    response::{IntoResponse, Response},
};
use bytes::Bytes;
use rust_embed::RustEmbed;
/// Frontend build (`bun run build` in `crates/admin/ui`).
#[derive(RustEmbed)]
#[folder = "ui/dist/"]
struct Ui;

// Generated by build.rs: brotli (quality 11) bytes of the compressible files in
// ui/dist. Clients without br get the global CompressionLayer's runtime gzip.
include!(concat!(env!("OUT_DIR"), "/precompressed.rs"));

const IMMUTABLE: HeaderValue = HeaderValue::from_static("public, max-age=31536000, immutable");
const NO_CACHE: HeaderValue = HeaderValue::from_static("no-cache");
const ACCEPT_ENCODING: HeaderValue = HeaderValue::from_static("accept-encoding");
/// A qvalue has at most three decimals (RFC 9110 §12.4.2), so it fits in thousandths.
const FULL_QUALITY: u16 = 1000;

fn content_type(path: &str) -> &'static str {
    match path.rsplit('.').next() {
        Some("html") => "text/html; charset=utf-8",
        Some("css") => "text/css; charset=utf-8",
        Some("js") => "text/javascript; charset=utf-8",
        Some("svg") => "image/svg+xml",
        Some("woff2") => "font/woff2",
        Some("woff") => "font/woff",
        Some("png") => "image/png",
        _ => "application/octet-stream",
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Encoding {
    /// The precompressed brotli bytes.
    Brotli,
    /// The embedded bytes; the CompressionLayer may still gzip them.
    Identity,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Caching {
    /// Hashed file names: the content behind a URL never changes.
    Immutable,
    /// HTML entry points: revalidated with an ETag on every navigation.
    Revalidate,
}

/// Brotli bytes of a file, when build.rs precompressed it.
fn precompressed(path: &str) -> Option<&'static [u8]> {
    let index = PRECOMPRESSED
        .binary_search_by_key(&path, |(candidate, _)| candidate)
        .ok()?;
    Some(PRECOMPRESSED[index].1)
}

/// Parses a qvalue into thousandths; `None` for anything outside RFC 9110's grammar.
fn parse_quality(text: &str) -> Option<u16> {
    let (whole, fraction) = text.split_once('.').unwrap_or((text, ""));
    if fraction.len() > 3 || !fraction.bytes().all(|byte| byte.is_ascii_digit()) {
        return None;
    }
    let thousandths = format!("{fraction:0<3}").parse::<u16>().ok()?;
    match whole {
        "0" => Some(thousandths),
        "1" if thousandths == 0 => Some(FULL_QUALITY),
        _ => None,
    }
}

/// Brotli when the client accepts it at least as much as gzip; otherwise the
/// embedded bytes, which the CompressionLayer gzips for clients that want it.
/// Without `Accept-Encoding` the response is identity.
fn negotiate(request: &HeaderMap) -> Encoding {
    let (mut brotli, mut gzip, mut any) = (None, None, None);
    let items = request
        .get_all(header::ACCEPT_ENCODING)
        .iter()
        .filter_map(|value| value.to_str().ok())
        .flat_map(|value| value.split(','));
    for item in items {
        let mut parts = item.split(';');
        let coding = parts.next().unwrap_or_default().trim();
        let mut quality = Some(FULL_QUALITY);
        for parameter in parts {
            if let Some((name, value)) = parameter.split_once('=')
                && name.trim().eq_ignore_ascii_case("q")
            {
                quality = parse_quality(value.trim());
            }
        }
        // An unreadable qvalue makes the whole entry unusable.
        let Some(quality) = quality else { continue };
        if coding.eq_ignore_ascii_case("br") {
            brotli = Some(quality);
        } else if coding.eq_ignore_ascii_case("gzip") || coding.eq_ignore_ascii_case("x-gzip") {
            gzip = Some(quality);
        } else if coding == "*" {
            any = Some(quality);
        }
    }
    let brotli = brotli.or(any).unwrap_or(0);
    let gzip = gzip.or(any).unwrap_or(0);
    match brotli > 0 && brotli >= gzip {
        true => Encoding::Brotli,
        false => Encoding::Identity,
    }
}

/// Brotli bytes are a fixed representation with a strong validator. Identity
/// responses may still be gzipped by the CompressionLayer, so theirs is weak.
fn entity_tag(hash: &[u8; 32], encoding: Encoding) -> String {
    let hex = base16ct::lower::encode_string(hash);
    match encoding {
        Encoding::Brotli => format!("\"{hex}-br\""),
        Encoding::Identity => format!("W/\"{hex}\""),
    }
}

/// `If-None-Match` uses the weak comparison (RFC 9110 §13.1.2).
fn not_modified(request: &HeaderMap, etag: &str) -> bool {
    request
        .get_all(header::IF_NONE_MATCH)
        .iter()
        .filter_map(|value| value.to_str().ok())
        .flat_map(|value| value.split(','))
        .map(str::trim)
        .any(|tag| tag == "*" || weak(tag) == weak(etag))
}

fn weak(tag: &str) -> &str {
    tag.strip_prefix("W/").unwrap_or(tag)
}

/// Embedded bytes are `'static`: serve them without copying.
fn static_body(data: Cow<'static, [u8]>) -> Bytes {
    match data {
        Cow::Borrowed(bytes) => Bytes::from_static(bytes),
        Cow::Owned(bytes) => Bytes::from(bytes),
    }
}

fn ui_file(path: &str, request: &HeaderMap, caching: Caching) -> Response {
    let Some(file) = Ui::get(path) else {
        return StatusCode::NOT_FOUND.into_response();
    };
    let variants = precompressed(path);
    let encoding = match variants {
        Some(_) => negotiate(request),
        None => Encoding::Identity,
    };

    let mut headers = HeaderMap::new();
    headers.insert(
        header::CACHE_CONTROL,
        match caching {
            Caching::Immutable => IMMUTABLE,
            Caching::Revalidate => NO_CACHE,
        },
    );
    if variants.is_some() {
        headers.insert(header::VARY, ACCEPT_ENCODING);
    }
    if caching == Caching::Revalidate {
        let etag = entity_tag(&file.metadata.sha256_hash(), encoding);
        let value = HeaderValue::from_str(&etag).expect("a hex entity tag is a valid header value");
        headers.insert(header::ETAG, value);
        if not_modified(request, &etag) {
            return (StatusCode::NOT_MODIFIED, headers).into_response();
        }
    }
    headers.insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static(content_type(path)),
    );
    let body = match (encoding, variants) {
        (Encoding::Brotli, Some(brotli)) => {
            // The global CompressionLayer skips responses that already carry a Content-Encoding.
            headers.insert(header::CONTENT_ENCODING, HeaderValue::from_static("br"));
            Bytes::from_static(brotli)
        }
        _ => static_body(file.data),
    };
    (headers, Body::from(body)).into_response()
}

/// Hashed assets are immutable; the reference's HTML always revalidates.
pub(crate) async fn asset(Path(file): Path<String>, request: HeaderMap) -> Response {
    let caching = match file.ends_with(".html") {
        true => Caching::Revalidate,
        false => Caching::Immutable,
    };
    ui_file(&format!("assets/{file}"), &request, caching)
}

/// Every panel route returns the SPA's `index.html` (client-side routing).
/// The page itself holds no data: everything comes from the authenticated API.
pub(crate) async fn spa(request: HeaderMap) -> Response {
    ui_file("index.html", &request, Caching::Revalidate)
}

/// The same bundle has a separate entry mode without project session handoff.
/// The rewritten page is built once and revalidated with an ETag like `spa`.
pub(crate) async fn controller_spa(request: HeaderMap) -> Response {
    static PAGE: OnceLock<Option<(String, String)>> = OnceLock::new();
    let Some((html, etag)) = PAGE.get_or_init(|| {
        let file = Ui::get("index.html")?;
        let html = String::from_utf8_lossy(&file.data).replacen(
            "<head>",
            "<head><meta name=\"nelcota-updates-controller\" content=\"1\">",
            1,
        );
        let hash = <sha2::Sha256 as sha2::Digest>::digest(html.as_bytes());
        let etag = format!("\"{}-controller\"", base16ct::lower::encode_string(&hash));
        Some((html, etag))
    }) else {
        return StatusCode::NOT_FOUND.into_response();
    };
    let mut headers = HeaderMap::new();
    headers.insert(header::CACHE_CONTROL, NO_CACHE);
    headers.insert(
        header::ETAG,
        HeaderValue::from_str(etag).expect("a hex entity tag is a valid header value"),
    );
    if not_modified(&request, etag) {
        return (StatusCode::NOT_MODIFIED, headers).into_response();
    }
    headers.insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("text/html; charset=utf-8"),
    );
    (headers, html.clone()).into_response()
}

#[cfg(test)]
mod tests {
    use std::io::Read;

    use axum::{Router, body::to_bytes, http::Request, routing::get};
    use tower::ServiceExt;
    use tower_http::compression::CompressionLayer;

    use super::*;

    fn accept(value: &str) -> HeaderMap {
        let mut headers = HeaderMap::new();
        headers.insert(
            header::ACCEPT_ENCODING,
            HeaderValue::from_str(value).unwrap(),
        );
        headers
    }

    fn decode(encoding: Option<&HeaderValue>, body: &[u8]) -> Vec<u8> {
        let mut decoded = Vec::new();
        match encoding.map(|value| value.to_str().unwrap()) {
            Some("br") => {
                brotli::Decompressor::new(body, 4096)
                    .read_to_end(&mut decoded)
                    .unwrap();
            }
            Some("gzip") => {
                flate2::read::GzDecoder::new(body)
                    .read_to_end(&mut decoded)
                    .unwrap();
            }
            None => decoded.extend_from_slice(body),
            Some(other) => panic!("unexpected content encoding {other}"),
        }
        decoded
    }

    /// The largest precompressed script, so the test follows every rebuild of dist.
    fn script() -> &'static str {
        PRECOMPRESSED
            .iter()
            .filter(|(path, _)| path.ends_with(".js"))
            .max_by_key(|(path, _)| Ui::get(path).map_or(0, |file| file.data.len()))
            .map(|(path, _)| path.strip_prefix("assets/").unwrap())
            .expect("dist has precompressed scripts")
    }

    async fn body(response: Response) -> Vec<u8> {
        to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap()
            .to_vec()
    }

    #[test]
    fn prefers_brotli_unless_the_client_ranks_gzip_higher() {
        assert_eq!(negotiate(&HeaderMap::new()), Encoding::Identity);
        assert_eq!(
            negotiate(&accept("gzip, deflate, br, zstd")),
            Encoding::Brotli
        );
        assert_eq!(negotiate(&accept("BR;Q=0.5")), Encoding::Brotli);
        assert_eq!(negotiate(&accept("*")), Encoding::Brotli);
        // Gzip-only or gzip-preferring clients get identity, gzipped by the layer.
        assert_eq!(negotiate(&accept("gzip")), Encoding::Identity);
        assert_eq!(
            negotiate(&accept("gzip;q=1.0, br;q=0.1")),
            Encoding::Identity
        );
        assert_eq!(negotiate(&accept("gzip;q=0.5, br;q=0.5")), Encoding::Brotli);
        assert_eq!(negotiate(&accept("identity")), Encoding::Identity);
        assert_eq!(negotiate(&accept("")), Encoding::Identity);
    }

    #[test]
    fn honors_q_zero_and_ignores_malformed_qvalues() {
        assert_eq!(negotiate(&accept("br;q=0, gzip")), Encoding::Identity);
        assert_eq!(negotiate(&accept("*;q=0")), Encoding::Identity);
        assert_eq!(negotiate(&accept("*;q=0, br;q=0.1")), Encoding::Brotli);
        assert_eq!(negotiate(&accept("br;q=0, *")), Encoding::Identity);
        assert_eq!(negotiate(&accept("br;q=abc")), Encoding::Identity);
        assert_eq!(negotiate(&accept("br;q=1.5")), Encoding::Identity);
        assert_eq!(negotiate(&accept("br;q=0.0001")), Encoding::Identity);
        assert_eq!(parse_quality("1.000"), Some(FULL_QUALITY));
        assert_eq!(parse_quality("0.25"), Some(250));
        assert_eq!(parse_quality("-0"), None);
    }

    #[test]
    fn every_variant_decompresses_to_the_embedded_file() {
        assert!(!PRECOMPRESSED.is_empty());
        assert!(
            PRECOMPRESSED.windows(2).all(|pair| pair[0].0 < pair[1].0),
            "sorted for binary search"
        );
        let br = HeaderValue::from_static("br");
        for (path, brotli) in PRECOMPRESSED {
            let original = Ui::get(path)
                .unwrap_or_else(|| panic!("{path} is embedded"))
                .data;
            assert!(brotli.len() < original.len(), "{path}");
            assert_eq!(decode(Some(&br), brotli), original.as_ref(), "{path}");
        }
        assert!(precompressed("index.html").is_some());
        assert!(
            PRECOMPRESSED
                .iter()
                .all(|(path, _)| !path.ends_with(".png") && !path.ends_with(".woff2"))
        );
    }

    #[tokio::test]
    async fn serves_brotli_or_identity_with_unchanged_type_and_cache_headers() {
        let file = script();
        let original = Ui::get(&format!("assets/{file}")).unwrap().data;
        for (accepted, expected) in [("br, gzip", Some("br")), ("gzip", None), ("identity", None)] {
            let response = asset(Path(file.to_owned()), accept(accepted)).await;
            assert_eq!(response.status(), StatusCode::OK);
            let headers = response.headers().clone();
            assert_eq!(
                headers[header::CONTENT_TYPE],
                "text/javascript; charset=utf-8"
            );
            assert_eq!(
                headers[header::CACHE_CONTROL],
                "public, max-age=31536000, immutable"
            );
            assert_eq!(headers[header::VARY], "accept-encoding");
            assert_eq!(
                headers
                    .get(header::CONTENT_ENCODING)
                    .map(|value| value.to_str().unwrap()),
                expected
            );
            assert!(headers.get(header::ETAG).is_none());
            let bytes = body(response).await;
            assert_eq!(
                decode(headers.get(header::CONTENT_ENCODING), &bytes),
                original.as_ref(),
                "{accepted}"
            );
        }
        // Already compressed formats keep a single identity representation.
        let image = Ui::iter()
            .find(|path| path.ends_with(".png"))
            .expect("dist has images");
        let response = asset(
            Path(image.strip_prefix("assets/").unwrap().to_owned()),
            accept("br"),
        )
        .await;
        assert!(response.headers().get(header::CONTENT_ENCODING).is_none());
        assert!(response.headers().get(header::VARY).is_none());
    }

    #[tokio::test]
    async fn index_has_a_strong_brotli_etag_a_weak_identity_one_and_answers_304() {
        let plain = spa(HeaderMap::new()).await;
        let brotli = spa(accept("br")).await;
        assert_eq!(plain.headers()[header::CACHE_CONTROL], "no-cache");
        assert_eq!(
            plain.headers()[header::CONTENT_TYPE],
            "text/html; charset=utf-8"
        );
        let plain_tag = plain.headers()[header::ETAG].to_str().unwrap().to_owned();
        let brotli_tag = brotli.headers()[header::ETAG].to_str().unwrap().to_owned();
        assert!(plain_tag.starts_with("W/\""), "{plain_tag}");
        assert!(brotli_tag.starts_with('"') && brotli_tag.ends_with("-br\""));

        let mut request = accept("br");
        for candidate in [
            brotli_tag.clone(),
            format!("W/{brotli_tag}"),
            format!("\"other\", {brotli_tag}"),
            "*".to_owned(),
        ] {
            request.insert(
                header::IF_NONE_MATCH,
                HeaderValue::from_str(&candidate).unwrap(),
            );
            let response = spa(request.clone()).await;
            assert_eq!(response.status(), StatusCode::NOT_MODIFIED, "{candidate}");
            assert_eq!(response.headers()[header::ETAG], brotli_tag.as_str());
            assert!(body(response).await.is_empty());
        }
        // The identity tag revalidates identity (and the layer's gzip of it).
        let mut identity = HeaderMap::new();
        identity.insert(
            header::IF_NONE_MATCH,
            HeaderValue::from_str(&plain_tag).unwrap(),
        );
        assert_eq!(spa(identity).await.status(), StatusCode::NOT_MODIFIED);
        // A tag of another representation sends the page again.
        request.insert(
            header::IF_NONE_MATCH,
            HeaderValue::from_str(&plain_tag).unwrap(),
        );
        let response = spa(request).await;
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(response.headers()[header::CONTENT_ENCODING], "br");
    }

    #[tokio::test]
    async fn controller_page_is_built_once_and_answers_304() {
        let response = controller_spa(HeaderMap::new()).await;
        assert_eq!(response.status(), StatusCode::OK);
        let etag = response.headers()[header::ETAG]
            .to_str()
            .unwrap()
            .to_owned();
        assert_eq!(response.headers()[header::CACHE_CONTROL], "no-cache");
        let html = String::from_utf8(body(response).await).unwrap();
        assert!(html.contains("nelcota-updates-controller"));
        let mut request = HeaderMap::new();
        request.insert(header::IF_NONE_MATCH, HeaderValue::from_str(&etag).unwrap());
        let response = controller_spa(request).await;
        assert_eq!(response.status(), StatusCode::NOT_MODIFIED);
        assert!(body(response).await.is_empty());
    }

    #[tokio::test]
    async fn the_compression_layer_gzips_identity_and_leaves_brotli_alone() {
        let file = script();
        let original = Ui::get(&format!("assets/{file}")).unwrap().data;
        let app = Router::new()
            .route("/admin/assets/{*file}", get(asset))
            .route("/admin/", get(spa))
            .layer(CompressionLayer::new());
        for (uri, accepted, expected) in [
            (format!("/admin/assets/{file}"), "gzip, br", "br"),
            (format!("/admin/assets/{file}"), "gzip", "gzip"),
            ("/admin/".to_owned(), "gzip", "gzip"),
        ] {
            let request = Request::get(&uri)
                .header(header::ACCEPT_ENCODING, accepted)
                .body(Body::empty())
                .unwrap();
            let response = app.clone().oneshot(request).await.unwrap();
            let headers = response.headers().clone();
            assert_eq!(
                headers
                    .get_all(header::CONTENT_ENCODING)
                    .iter()
                    .collect::<Vec<_>>(),
                [expected],
                "{uri}"
            );
            assert_eq!(headers.get_all(header::VARY).iter().count(), 1, "{uri}");
            let bytes = body(response).await;
            let decoded = decode(headers.get(header::CONTENT_ENCODING), &bytes);
            if uri.ends_with(".js") {
                assert_eq!(decoded, original.as_ref());
            } else {
                assert!(
                    String::from_utf8(decoded)
                        .unwrap()
                        .contains("<div id=\"app\">")
                );
            }
        }
    }
}
